  async function loadSummary(){const payload=await api('/summary');state.summary=payload;state.policies=payload.keys||[];scheduleBudgetBoundaryRefresh();render()}
  async function loadModels(){const payload=await api('/models');state.models=(payload.models||[]).filter(model=>model.available!==false);return state.models}
  async function loadRates(){const payload=await api('/rates');state.rates=payload.rates||[];return state.rates}
  // Read downstream API Keys from CPA's canonical configuration endpoint.
  // CPA Home can claim the similarly named /api-keys route for its wallet UI,
  // so the panel must not call that ambiguous route.
  async function loadKeys(){const payload=await host('/config');state.rawKeys=extractCPAKeys(payload);return state.rawKeys}
  async function loadSelected(){await Promise.all([loadTrend(),loadSelectedLogs()]);render()}
  async function loadTrend(){if(!state.selected){state.trend={points:[]};state.trendError='';return}const from=$('analysis-from').value,to=$('analysis-to').value,params=new URLSearchParams({key_id:state.selected,from,to,timezone:Intl.DateTimeFormat().resolvedOptions().timeZone||'Asia/Shanghai',granularity:$('analysis-granularity').value||'hour'});try{state.trend=await api('/analysis?'+params);state.trendError='';if($('analysis-preset')?.value==='today'&&($('analysis-granularity')?.value||'hour')==='hour')state.keyTrends[state.selected]=state.trend.points||[]}catch(error){state.trend={points:[]};state.trendError=errorMessage(error)}}
