  // The public ranking is an all-Key daily rollup and never follows drawer selection.
  async function loadDailyModelRanking(){const range=todayRange(),params=new URLSearchParams(range);try{state.dailyModelUsage=await api('/model-ranking?'+params);state.dailyModelUsageError=''}catch(error){state.dailyModelUsage={models:[]};state.dailyModelUsageError=errorMessage(error)}renderDailyModelRanking()}
  async function loadSelectedLogs(){if(!state.selected){state.selectedLogs=[];return}const params=new URLSearchParams({key_id:state.selected,page:'1',page_size:'4'}),payload=await api('/logs?'+params);state.selectedLogs=payload.logs||[]}
