  async function syncCPAModels(){const authPayload=await host('/auth-files'),auths=enabledCPAAuthEntries(authPayload);if(!auths.length)throw new Error(uiText('CPA 当前没有已启用账号，无法同步支持的模型。','CPA has no enabled accounts to synchronize supported models from.'));const results=await Promise.allSettled(auths.map(auth=>host('/auth-files/models?name='+encodeURIComponent(value(auth.id||auth.name))))),failed=results.filter(result=>result.status==='rejected').length;if(failed)throw new Error(uiText('有 '+failed+' 个 CPA 账号的模型读取失败，未覆盖现有模型目录，请稍后重试。',failed+' CPA account model catalogs failed to load. The existing catalog was kept; retry later.'));const seen=new Map;results.forEach((result,index)=>{const auth=auths[index];(result.value?.models||[]).forEach(model=>{const id=value(model.id||model.name);if(id&&!seen.has(id))seen.set(id,{id,display_name:value(model.display_name||model.displayName||id),owner:value(model.owned_by||model.owner||model.type||auth.provider||auth.type)})})});if(!seen.size)throw new Error(uiText('CPA 当前账号未返回支持的模型。','CPA accounts returned no supported models.'));const models=Array.from(seen.values());await api('/models',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({models})});state.models=models.map(model=>({...model,available:true,synced_at:new Date().toISOString()}));return models.length}
