  function policyModelEntries(policy){const selected=new Set(policy?.allowed_models||[]),entries=new Map;state.models.forEach(model=>{const id=value(model.id);if(id)entries.set(id,{id,display:value(model.display_name||model.id)})});selected.forEach(id=>{if(!entries.has(id))entries.set(id,{id,display:id})});return Array.from(entries.values()).sort((a,b)=>a.display.localeCompare(b.display))}
  function renderPolicyModels(){const dialog=$('policy-dialog'),selected=dialog.__allowedModels||new Set,query=value($('allowed-models-search')?.value).toLowerCase(),entries=policyModelEntries({allowed_models:Array.from(selected)}).filter(model=>!query||(model.id+' '+model.display).toLowerCase().includes(query));$('allowed-models-summary').textContent=selected.size?uiText('仅允许 ','Allow only ')+number(selected.size)+uiText(' 个模型',' models'):uiText('未限制（全部模型）','Unrestricted (all models)');$('allowed-models-list').innerHTML=entries.length?entries.map(model=>'<label class="policy-model-item"><input type="checkbox" data-allowed-model="'+escapeHTML(model.id)+'" '+(selected.has(model.id)?'checked':'')+'><span><strong>'+escapeHTML(model.display)+'</strong><small>'+escapeHTML(model.id)+'</small></span></label>').join(''):'<div class="empty">'+uiText('暂无模型目录，请先同步 CPA 模型。','No model catalog yet. Synchronize CPA models first.')+'</div>'}
  const weekdayLabels=()=>uiText(['周一','周二','周三','周四','周五','周六','周日'],['Mon','Tue','Wed','Thu','Fri','Sat','Sun']);
  function accessRuleCard(rule={}){const card=document.createElement('div'),selected=new Set(rule.weekdays||[1,2,3,4,5,6,7]);card.className='access-rule';card.dataset.accessRule='';card.innerHTML='<div class="access-rule-head"><strong>'+uiText('访问时段','Access time slot')+'</strong><button type="button" class="access-rule-remove"><svg class="cc-icon"><use href="#cc-icon-trash"></use></svg>'+uiText('移除','Remove')+'</button></div><div class="form-grid"><label>'+uiText('开始时间','Start time')+'<input class="access-start" type="time" value="'+escapeHTML(rule.start||'08:00')+'"></label><label>'+uiText('结束时间','End time')+'<input class="access-end" type="time" value="'+escapeHTML(rule.end||'18:00')+'"></label></div><div class="access-weekdays">'+weekdayLabels().map((day,index)=>'<label><input type="checkbox" value="'+(index+1)+'" '+(selected.has(index+1)?'checked':'')+'>'+day+'</label>').join('')+'</div><small>'+uiText('开始时间晚于结束时间时，此时段跨午夜。','A start later than the end continues past midnight.')+'</small>';card.querySelector('.access-rule-remove').onclick=()=>{card.remove();if(!$('access-rule-list').children.length){$('access-limited').checked=false;setAccessLimited(false)}};return card}
  function addAccessRule(rule={}){const list=$('access-rule-list');if(list.children.length>=16){say(uiText('一个 Key 最多配置 16 个访问时段。','A Key supports at most 16 access time slots.'));return}list.append(accessRuleCard(rule))}
