  function readAccessPolicy(){if(!$('access-limited').checked)return {access_rules:[],access_timezone:''};const accessRules=Array.from(document.querySelectorAll('#access-rule-list [data-access-rule]')).map(card=>({weekdays:Array.from(card.querySelectorAll('.access-weekdays input:checked')).map(input=>Number(input.value)),start:value(card.querySelector('.access-start').value),end:value(card.querySelector('.access-end').value)})),accessTimezone=value($('access-timezone').value);if(!accessRules.length||accessRules.some(rule=>!rule.weekdays.length))throw new Error(uiText('每个访问时段至少选择一个星期。','Select at least one weekday for every access time slot.'));if(accessRules.some(rule=>!rule.start||!rule.end||rule.start===rule.end))throw new Error(uiText('每个访问时段必须设置不同的开始和结束时间。','Every access time slot needs different start and end times.'));if(!accessTimezone)throw new Error(uiText('请填写 IANA 时区，例如 Asia/Shanghai。','Enter an IANA time zone, for example Asia/Shanghai.'));return {access_rules:accessRules,access_timezone:accessTimezone}}
  function openPolicy(policy){state.editing=policy||null;const dialog=$('policy-dialog');dialog.__allowedModels=new Set(policy?.allowed_models||[]);$('source').replaceChildren();state.rawKeys.forEach((key,index)=>{const option=document.createElement('option');option.value=String(index);option.textContent='CPA Key '+(index+1)+' · ••••'+String(key).slice(-4);$('source').append(option)});if(!state.rawKeys.length){const option=document.createElement('option');option.value='';option.textContent=uiText('CPA 未配置 API Key','CPA has no configured API Key');$('source').append(option)}$('source').disabled=Boolean(policy);$('name').value=policy?.name||'';$('enabled').value=policy?.enabled?'true':'false';$('five-hour-budget').value=Number(policy?.five_hour_budget_usd)>0?String(policy.five_hour_budget_usd):'';$('seven-day-budget').value=Number(policy?.seven_day_budget_usd)>0?String(policy.seven_day_budget_usd):'';$('allowed-models-search').value='';renderPolicyModels();fillAccessPolicy(policy);dialog.showModal()}
  async function savePolicy(){const name=value($('name').value);if(!name){say(uiText('请输入 Key 备注名称。','Enter a Key name.'));return}const parseBudget=id=>{const n=Number($(id).value);return Number.isFinite(n)&&n>0?n:0};const raw=state.editing?null:state.rawKeys[Number($('source').value)];if(!state.editing&&!raw){say(uiText('请先在 CPA 配置并选择 API Key。','Configure and select an API Key in CPA first.'));return}let access;try{access=readAccessPolicy()}catch(error){say(error.message);return}const policy={id:state.editing?.id||'key-'+(crypto.randomUUID?.()||Date.now().toString(36)),name,enabled:$('enabled').value==='true',allowed_models:Array.from($('policy-dialog').__allowedModels||[]),five_hour_budget_usd:parseBudget('five-hour-budget'),seven_day_budget_usd:parseBudget('seven-day-budget'),...access};try{await api('/keys',{method:state.editing?'PUT':'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({policy,api_key:raw})});closeDialog('policy-dialog');await loadSummary();say(uiText('额度设置已保存。','Quota settings saved.'),true)}catch(error){say(error.message)}}
