  let rateEntries=new Map;
  function filterRateRows(){const query=value($('rate-card-search')?.value).toLowerCase(),status=value($('rate-card-status-filter')?.value),rows=Array.from(document.querySelectorAll('#rate-card-rows .rate-card-row'));let visible=0;rows.forEach(row=>{const matchesQuery=!query||value(row.dataset.rateSearch).includes(query),matchesStatus=!status||row.dataset.rateStatus===status;row.hidden=!(matchesQuery&&matchesStatus);if(!row.hidden)visible++});$('rate-card-filter-empty').hidden=visible>0||rows.length===0}
