  async function saveRates(){const rates=[];document.querySelectorAll('.rate-card-row').forEach(row=>{const model=decodeURIComponent(row.dataset.rateModel||'');if(!model)return;const read=name=>{const n=Number(row.querySelector('[data-rate="'+name+'"]').value);return Number.isFinite(n)&&n>=0?n:0};const inputs=Array.from(row.querySelectorAll('input'));const configured=inputs.some(input=>value(input.value)!=='');if(configured)rates.push({model,input_usd_per_million:read('input'),cached_usd_per_million:read('cached'),output_usd_per_million:read('output')})});try{const payload=await api('/rates',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({rates})});state.rates=payload.rates||[];rateEntries=new Map(state.rates.map(rate=>[value(rate.model),rate]));closeDialog('rate-card-dialog');render();say(uiText('模型费率已保存。','Model rates saved.'),true)}catch(error){say(error.message)}}
